import yaml
src=open('claude-dev-log-diary/day-009.md',encoding='utf-8').read()
d=yaml.safe_load(open('.coordination/mining/v2/day-009.yaml'))
def norm(s): return ' '.join(s.split())
nsrc=norm(src)
bad=[]
def chk(q,where):
    for line in q.strip().split('\n'):
        line=norm(line)
        if len(line)<8: continue
        if line not in nsrc: bad.append((where,line[:90]))
for p in d['philosophy']:
    if p['source']=='user-verbatim': chk(p['quote'],p['loc'])
for r in d['skill_rules']:
    if r.get('quote'): chk(r['quote'],r['rule_id'])
for f in d['failure_modes']: chk(f['quote'],f['loc'])
for p in d['pairing_rules']:
    if p.get('quote'): chk(p['quote'],p['rule_id'])
print('MISMATCHES:',len(bad))
for b in bad: print(b)
